// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./X402Gateway.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

contract X402Factory is Ownable, Pausable {
    // Array to keep track of all deployed gateways
    X402Gateway[] public allGateways;

    // Mapping from owner address to their deployed gateways
    mapping(address => X402Gateway[]) public getGatewaysByOwner;

    event GatewayCreated(address indexed gatewayAddress, address indexed owner, address usdc, uint256 initialPriceERC20, uint256 initialPriceNative);

    constructor() Ownable(msg.sender) {}

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @dev Deploys a new X402Gateway contract
     * @param _usdc The address of the USDC token (or address(0) for strictly native Arc testnet without ERC20 bindings)
     * @param _initialPriceERC20 The initial price per API call (in token smallest units, 6 decimals usually)
     * @param _initialPriceNative The initial price per API call for native USDC on Arc (18 decimals)
     * @return gateway The deployed X402Gateway contract address
     */
    function createGateway(address _usdc, uint256 _initialPriceERC20, uint256 _initialPriceNative) external whenNotPaused returns (address gateway) {
        // Deploy a new gateway with the caller as the initial owner
        X402Gateway newGateway = new X402Gateway(_usdc, _initialPriceERC20, _initialPriceNative, msg.sender);

        // Store the gateway
        allGateways.push(newGateway);
        getGatewaysByOwner[msg.sender].push(newGateway);

        emit GatewayCreated(address(newGateway), msg.sender, _usdc, _initialPriceERC20, _initialPriceNative);

        return address(newGateway);
    }

    /**
     * @dev Returns all gateways created by a specific owner
     */
    function getOwnerGateways(address owner) external view returns (X402Gateway[] memory) {
        return getGatewaysByOwner[owner];
    }

    /**
     * @dev Returns total number of gateways deployed
     */
    function allGatewaysLength() external view returns (uint256) {
        return allGateways.length;
    }
}

