// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

contract X402Gateway is Ownable, Pausable, ReentrancyGuard {
    IERC20 public immutable usdc;
    uint256 public pricePerCall; // Assumes 6 decimals for ERC20 and 18 for Native if not carefully managed. Usually, we can use different prices or handle it in off-chain logic.
    uint256 public nativePricePerCall; // 18 decimals for Arc Native USDC

    event PaymentReceived(address indexed payer, uint256 amount, string endpoint, bool isNative);
    event PriceUpdated(uint256 newPriceERC20, uint256 newPriceNative);

    constructor(address _usdc, uint256 _initialPriceERC20, uint256 _initialPriceNative, address _initialOwner) Ownable(_initialOwner) {
        usdc = IERC20(_usdc);
        pricePerCall = _initialPriceERC20;
        nativePricePerCall = _initialPriceNative;
    }

    function setPrice(uint256 _newPriceERC20, uint256 _newPriceNative) external onlyOwner {
        pricePerCall = _newPriceERC20;
        nativePricePerCall = _newPriceNative;
        emit PriceUpdated(_newPriceERC20, _newPriceNative);
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    // ==========================================
    // BASE NETWORK (ERC-20 USDC)
    // ==========================================

    function pay(string calldata endpoint) external whenNotPaused nonReentrant {
        require(pricePerCall > 0, "ERC20 Price not set");
        require(address(usdc) != address(0), "USDC not configured");
        require(usdc.transferFrom(msg.sender, address(this), pricePerCall), "Payment failed");
        emit PaymentReceived(msg.sender, pricePerCall, endpoint, false);
    }

    function payExact(uint256 amount, string calldata endpoint) external whenNotPaused nonReentrant {
        require(amount >= pricePerCall, "Insufficient amount");
        require(address(usdc) != address(0), "USDC not configured");
        require(usdc.transferFrom(msg.sender, address(this), amount), "Payment failed");
        emit PaymentReceived(msg.sender, amount, endpoint, false);
    }

    function withdraw(address to) external onlyOwner nonReentrant {
        require(address(usdc) != address(0), "USDC not configured");
        uint256 balance = usdc.balanceOf(address(this));
        require(balance > 0, "No funds to withdraw");
        require(usdc.transfer(to, balance), "Withdrawal failed");
    }

    // ==========================================
    // ARC NETWORK (NATIVE USDC)
    // ==========================================

    function payNative(string calldata endpoint) external payable whenNotPaused nonReentrant {
        require(nativePricePerCall > 0, "Native Price not set");
        require(msg.value >= nativePricePerCall, "Insufficient native amount");
        emit PaymentReceived(msg.sender, msg.value, endpoint, true);
    }

    function withdrawNative(address to) external onlyOwner nonReentrant {
        uint256 balance = address(this).balance;
        require(balance > 0, "No native funds to withdraw");
        (bool success, ) = to.call{value: balance}("");
        require(success, "Native withdrawal failed");
    }
}

